func (p *Provider) PreCAPIInstallOnBootstrap(ctx context.Context, cluster *types.Cluster, clusterSpec *cluster.Spec) error {
	if !p.setupTinkerbell {
		return nil
	}

	logger.V(4).Info("Installing Tinkerbell stack on bootstrap cluster")

	installer, err := p.newBootstrapTinkerbellInstaller(clusterSpec)
	if err != nil {
		return err
	}

	if err := installer.Install(ctx, cluster.KubeconfigFile); err != nil {
		return err
	}

	return nil
}

type tinkerbellInstaller interface {
	Install(ctx context.Context, kubeconfigFile string) error
}

type tinkerbellInstallerFunc func(ctx context.Context, kubeconfigFile string) error

func (f tinkerbellInstallerFunc) Install(ctx context.Context, kubeconfigFile string) error {
	return f(ctx, kubeconfigFile)
}

func (p *Provider) newBootstrapTinkerbellInstaller(clusterSpec *cluster.Spec) (tinkerbellInstaller, error) {
	ip, err := networkutils.GetLocalIP(p.netClient)
	if err != nil {
		return nil, err
	}

	stack := newStack(clusterSpec.VersionsBundle.Tinkerbell.TinkerbellStack, p.docker, p.writer, p.helm, ip.String()).
		withNamespace(constants.EksaSystemNamespace, false).
		withoutBoots().
		withHegel().
		withTinkController().
		withTinkServer()

	return tinkerbellInstallerFunc(func(ctx context.Context, kubeconfigFile string) error {
		if err := stack.install(ctx, kubeconfigFile); err != nil {
			return fmt.Errorf("install Tinkerbell stack on bootstrap cluster: %v", err)
		}

		if err := stack.installBootsOnDocker(ctx, kubeconfigFile); err != nil {
			return err
		}

		return nil
	}), nil
}

func (p *Provider) newWorkloadTinkerbellInstaller(clusterSpec *cluster.Spec) (tinkerbellInstaller, error) {
	ip, err := networkutils.GetLocalIP(p.netClient)
	if err != nil {
		return nil, err
	}

	stack := newStack(clusterSpec.VersionsBundle.Tinkerbell.TinkerbellStack, p.docker, p.writer, p.helm, ip.String()).
		withNamespace(constants.EksaSystemNamespace, true).
		withBoots().
		withHegel().
		withTinkController().
		withTinkServer()

	return tinkerbellInstallerFunc(func(ctx context.Context, kubeconfigFile string) error {
		if err := stack.install(ctx, kubeconfigFile); err != nil {
			return fmt.Errorf("install stack on workload cluster: %v", err)
		}

		logger.V(4).Info("Removing local boots container")
		if err := p.docker.ForceRemove(ctx, boots); err != nil {
			return fmt.Errorf("remove local boots container: %v", err)
		}

		return nil
	}), nil
}

func (p *Provider) PostBootstrapSetup(ctx context.Context, clusterConfig *v1alpha1.Cluster, cluster *types.Cluster) error {
	// hardwareSpec, err := hardware.MarshalCatalogue(p.catalogue)
	// if err != nil {
	// 	return fmt.Errorf("failed marshalling resources for hardware spec: %v", err)
	// }
	err := p.providerKubectlClient.ApplyKubeSpec(ctx, cluster, p.hardwareManifestPath)
	if err != nil {
		return fmt.Errorf("applying hardware yaml: %v", err)
	}
	return nil
}

func (p *Provider) PostWorkloadInit(ctx context.Context, cluster *types.Cluster, clusterSpec *cluster.Spec) error {
	if !p.setupTinkerbell {
		return nil
	}

	logger.V(4).Info("Installing Tinkerbell stack on workload cluster")

	installer, err := p.newWorkloadTinkerbellInstaller(clusterSpec)
	if err != nil {
		return err
	}

	if err := installer.Install(ctx, cluster.KubeconfigFile); err != nil {
		return err
	}

	return nil
}

